// Type: CallName.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct CallName {
    pub activation: u64,
    pub completion: u32,
    pub position: u32,
}

// Record: CallName.
impl Record for CallName {
    type Limits = Limits;
    const TAIL: Path = paths::CALL_NAME_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::U64, &self.activation, limits, out, paths::CALL_NAME_ACTIVATION)?;
        field::write(field::U32, &self.completion, limits, out, paths::CALL_NAME_COMPLETION)?;
        field::write(field::U32, &self.position, limits, out, paths::CALL_NAME_POSITION)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            activation: field::read(field::U64, limits, reader, paths::CALL_NAME_ACTIVATION)?,
            completion: field::read(field::U32, limits, reader, paths::CALL_NAME_COMPLETION)?,
            position: field::read(field::U32, limits, reader, paths::CALL_NAME_POSITION)?,
        })
    }
}

