// Type: Directory.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Directory {
    pub name: Box<[u8]>,
    pub path: Box<[u8]>,
    pub writable: bool,
    pub git: bool,
    pub conflicts: List<Box<[u8]>>,
}

// Record: Directory.
impl Record for Directory {
    type Limits = Limits;
    const TAIL: Path = paths::DIRECTORY_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 13)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 13)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::Text { limit: limits.directory_name.min(CEILINGS.directory_name) }, &self.name, limits, out, paths::DIRECTORY_NAME)?;
        field::write(field::Text { limit: limits.directory_path.min(CEILINGS.directory_path) }, &self.path, limits, out, paths::DIRECTORY_PATH)?;
        field::write(field::Boolean, &self.writable, limits, out, paths::DIRECTORY_WRITABLE)?;
        field::write(field::Boolean, &self.git, limits, out, paths::DIRECTORY_GIT)?;
        field::write(field::Sequence { limit: limits.directory_conflicts.min(CEILINGS.directory_conflicts), minimum: 4, item: field::Text { limit: limits.directory_conflicts_item.min(CEILINGS.directory_conflicts_item) } }, &self.conflicts, limits, out, paths::DIRECTORY_CONFLICTS)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            name: field::read(field::Text { limit: limits.directory_name.min(CEILINGS.directory_name) }, limits, reader, paths::DIRECTORY_NAME)?,
            path: field::read(field::Text { limit: limits.directory_path.min(CEILINGS.directory_path) }, limits, reader, paths::DIRECTORY_PATH)?,
            writable: field::read(field::Boolean, limits, reader, paths::DIRECTORY_WRITABLE)?,
            git: field::read(field::Boolean, limits, reader, paths::DIRECTORY_GIT)?,
            conflicts: field::read(field::Sequence { limit: limits.directory_conflicts.min(CEILINGS.directory_conflicts), minimum: 4, item: field::Text { limit: limits.directory_conflicts_item.min(CEILINGS.directory_conflicts_item) } }, limits, reader, paths::DIRECTORY_CONFLICTS)?,
        })
    }
}

