// Type: RunResult.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum RunResult {
    Accepted(Accepted),
    Parked,
    Failed(Failed),
    Refused(Refused),
}

// Record: RunResult.
impl Record for RunResult {
    type Limits = Limits;
    const TAIL: Path = paths::RUN_RESULT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 372)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 372)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Accepted(value) => { field::put(out, &[0], paths::RUN_RESULT_TAG)?; value.write(limits, out) },
            Self::Parked => field::put(out, &[1], paths::RUN_RESULT_TAG),
            Self::Failed(value) => { field::put(out, &[2], paths::RUN_RESULT_TAG)?; value.write(limits, out) },
            Self::Refused(value) => { field::put(out, &[3], paths::RUN_RESULT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::RUN_RESULT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Accepted(Accepted::read(limits, reader)?)),
            1 => Ok(Self::Parked),
            2 => Ok(Self::Failed(Failed::read(limits, reader)?)),
            3 => Ok(Self::Refused(Refused::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::RUN_RESULT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

// Type: Answer.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Answer {
    pub turns: u32,
    pub spent: u64,
    pub last_read: Option<u64>,
    pub result: RunResult,
}

// Record: Answer.
impl Record for Answer {
    type Limits = Limits;
    const TAIL: Path = paths::ANSWER_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 377)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 377)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::U32, &self.turns, limits, out, paths::ANSWER_TURNS)?;
        field::write(field::U64, &self.spent, limits, out, paths::ANSWER_SPENT)?;
        field::write(field::Optional { item: field::U64 }, &self.last_read, limits, out, paths::ANSWER_LAST_READ)?;
        field::write(field::Nested, &self.result, limits, out, paths::ANSWER_RESULT)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            turns: field::read(field::U32, limits, reader, paths::ANSWER_TURNS)?,
            spent: field::read(field::U64, limits, reader, paths::ANSWER_SPENT)?,
            last_read: field::read(field::Optional { item: field::U64 }, limits, reader, paths::ANSWER_LAST_READ)?,
            result: field::read(field::Nested, limits, reader, paths::ANSWER_RESULT)?,
        })
    }
}

